import { useState } from "react";

type Values = {
  email: string;
  password: string;
  confirm: string;
};

type Errors = Partial<Record<keyof Values, string>>;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: Values): Errors {
  const errors: Errors = {};
  if (!values.email.trim()) {
    errors.email = "Email is required";
  } else if (!EMAIL_RE.test(values.email.trim())) {
    errors.email = "Enter a valid email address";
  }
  if (!values.password) {
    errors.password = "Password is required";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters";
  }
  if (!values.confirm) {
    errors.confirm = "Please confirm your password";
  } else if (values.confirm !== values.password) {
    errors.confirm = "Passwords do not match";
  }
  return errors;
}

const EMPTY: Values = { email: "", password: "", confirm: "" };

export function SignupForm({
  onSubmit,
}: {
  onSubmit: (values: Values) => Promise<void>;
}) {
  const [values, setValues] = useState<Values>(EMPTY);
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);

  const setValue = (field: keyof Values) => (value: string) => {
    setValues((v) => ({ ...v, [field]: value }));
    // Clear the field's error as soon as the user edits it again.
    setErrors((e) => (e[field] ? { ...e, [field]: undefined } : e));
  };

  const handleBlur = (field: keyof Values) => () => {
    const fieldErrors = validate({
      ...values,
      [field]: values[field],
    });
    if (fieldErrors[field]) {
      setErrors((e) => ({ ...e, [field]: fieldErrors[field] }));
    } else {
      setErrors((e) => ({ ...e, [field]: undefined }));
    }
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextErrors = validate(values);
    setErrors(nextErrors);
    if (Object.values(nextErrors).some(Boolean)) return;

    setSubmitting(true);
    try {
      await onSubmit(values);
      setValues(EMPTY);
      setErrors({});
    } finally {
      setSubmitting(false);
    }
  };

  const describedBy = (field: keyof Values) =>
    errors[field] ? `${field}-error` : undefined;

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => setValue("email")(e.target.value)}
          onBlur={handleBlur("email")}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={describedBy("email")}
        />
        {errors.email && (
          <p role="alert" id="email-error">
            {errors.email}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => setValue("password")(e.target.value)}
          onBlur={handleBlur("password")}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={describedBy("password")}
        />
        {errors.password && (
          <p role="alert" id="password-error">
            {errors.password}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="confirm">Confirm password</label>
        <input
          id="confirm"
          type="password"
          value={values.confirm}
          onChange={(e) => setValue("confirm")(e.target.value)}
          onBlur={handleBlur("confirm")}
          aria-invalid={errors.confirm ? true : undefined}
          aria-describedby={describedBy("confirm")}
        />
        {errors.confirm && (
          <p role="alert" id="confirm-error">
            {errors.confirm}
          </p>
        )}
      </div>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up…" : "Sign up"}
      </button>
    </form>
  );
}

export default SignupForm;

