import { cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, it, vi } from "vitest";
import { SignupForm } from "./SignupForm";

afterEach(cleanup);

/** Deferred promise: lets the test control when onSubmit resolves. */
function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
}

const validValues = {
  email: "ada@example.com",
  password: "hunter2hunter2",
  confirm: "hunter2hunter2",
};

describe("SignupForm", () => {
  it("shows an error on blur of an invalid email", async () => {
    render(<SignupForm onSubmit={vi.fn()} />);
    const email = screen.getByRole("textbox", { name: /email/i });

    await userEvent.type(email, "not-an-email");
    email.blur();

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Enter a valid email address"
    );
    expect(screen.queryByText(/required/i)).toBeNull();
  });

  it("blocks submit when confirm does not match password", async () => {
    const onSubmit = vi.fn().mockResolvedValue(undefined);
    render(<SignupForm onSubmit={onSubmit} />);

    await userEvent.type(
      screen.getByRole("textbox", { name: /email/i }),
      validValues.email
    );
    await userEvent.type(
      screen.getByLabelText(/^password$/i),
      validValues.password
    );
    await userEvent.type(screen.getByLabelText(/confirm/i), "different");

    await userEvent.click(screen.getByRole("button", { name: /sign up/i }));

    expect(onSubmit).not.toHaveBeenCalled();
    expect(screen.getByRole("alert")).toHaveTextContent(
      "Passwords do not match"
    );
    // The mismatched field is flagged for assistive tech.
    expect(screen.getByLabelText(/confirm/i)).toBeInvalid();
  });

  it("disables the submit button while onSubmit is pending and resets on success", async () => {
    const d = deferred<void>();
    const onSubmit = vi.fn().mockReturnValue(d.promise);
    render(<SignupForm onSubmit={onSubmit} />);

    await userEvent.type(
      screen.getByRole("textbox", { name: /email/i }),
      validValues.email
    );
    await userEvent.type(
      screen.getByLabelText(/^password$/i),
      validValues.password
    );
    await userEvent.type(
      screen.getByLabelText(/confirm/i),
      validValues.confirm
    );

    const button = screen.getByRole("button", { name: /sign up/i });
    expect(button).toBeEnabled();

    await userEvent.click(button);

    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(onSubmit).toHaveBeenCalledWith(validValues);
    expect(button).toBeDisabled();

    d.resolve();
    await d.promise;

    expect(await screen.findByRole("button", { name: /sign up/i })).toBeEnabled();

    // Form reset on success.
    expect(screen.getByRole("textbox", { name: /email/i })).toHaveValue("");
    expect(screen.getByLabelText(/^password$/i)).toHaveValue("");
    expect(screen.getByLabelText(/confirm/i)).toHaveValue("");
  });

  it("wires errors to inputs via aria-describedby and aria-invalid", async () => {
    render(<SignupForm onSubmit={vi.fn()} />);

    const email = screen.getByRole("textbox", { name: /email/i });
    const password = screen.getByLabelText(/^password$/i);

    // No describedby/invalid wiring before any error exists.
    expect(email).toHaveAttribute("aria-describedby", "");
    expect(email).not.toBeInvalid();
    expect(password).not.toHaveAttribute("aria-describedby");
    expect(password).not.toBeInvalid();

    // Trigger errors on both fields via blur.
    await userEvent.type(email, "nope");
    email.blur();
    await screen.findByRole("alert");
    password.focus();
    password.blur();
    await screen.findByText(/at least 8 characters/i);

    // Email input points at its error element by id.
    const emailDescribedBy = email.getAttribute("aria-describedby");
    expect(emailDescribedBy).toBeTruthy();
    expect(document.getElementById(emailDescribedBy!)).toHaveTextContent(
      "Enter a valid email address"
    );
    expect(email).toBeInvalid();

    // Password input points at its own error element.
    const passwordDescribedBy = password.getAttribute("aria-describedby");
    expect(passwordDescribedBy).toBeTruthy();
    expect(passwordDescribedBy).not.toBe(emailDescribedBy);
    expect(document.getElementById(passwordDescribedBy!)).toHaveTextContent(
      "Password must be at least 8 characters"
    );
    expect(password).toBeInvalid();

    // Error elements are announced (role="alert").
    expect(screen.getAllByRole("alert")).toHaveLength(2);
  });

  it("calls onSubmit with valid values and does not reset on rejection", async () => {
    const onSubmit = vi.fn().mockRejectedValue(new Error("server down"));
    render(<SignupForm onSubmit={onSubmit} />);

    await userEvent.type(
      screen.getByRole("textbox", { name: /email/i }),
      validValues.email
    );
    await userEvent.type(
      screen.getByLabelText(/^password$/i),
      validValues.password
    );
    await userEvent.type(
      screen.getByLabelText(/confirm/i),
      validValues.confirm
    );

    await userEvent.click(screen.getByRole("button", { name: /sign up/i }));

    // Rejection propagates; values survive so the user can retry.
    await expect(onSubmit.mock.results[0]!.value).rejects.toThrow(
      "server down"
    );
    expect(screen.getByRole("textbox", { name: /email/i })).toHaveValue(
      validValues.email
    );
    // Button re-enabled after failure.
    expect(screen.getByRole("button", { name: /sign up/i })).toBeEnabled();
  });
});

