it("keeps values and re-enables the button when onSubmit rejects", async () => {
  const onSubmit = vi.fn().mockRejectedValue(new Error("server down"));
  render(<SignupForm onSubmit={onSubmit} />);

  await userEvent.type(
    screen.getByRole("textbox", { name: /email/i }),
    validValues.email
  );
  await userEvent.type(
    screen.getByLabelText(/^password$/i),
    validValues.password
  );
  await userEvent.type(
    screen.getByLabelText(/confirm/i),
    validValues.confirm
  );

  await userEvent.click(screen.getByRole("button", { name: /sign up/i }));

  expect(onSubmit).toHaveBeenCalledTimes(1);

  // Rejection keeps values so the user can retry...
  await waitFor(() => {
    expect(screen.getByRole("textbox", { name: /email/i })).toHaveValue(
      validValues.email
    );
    // ...and re-enables the submit button.
    expect(screen.getByRole("button", { name: /sign up/i })).toBeEnabled();
  });
});

